#include <Adafruit_NeoPixel.h>

// === НАСТРОЙКИ ===
#define LED_PIN 6          // Сигнальный провод ленты подключён к D6
#define NUM_LEDS 60        // Количество светодиодов на ленте (у тебя 60)
#define TOUCH_PIN 2        // Выход TTP223 подключён к D2

// Создаём объект для управления лентой
Adafruit_NeoPixel strip(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

// Переменные для работы сенсора и таймингов
unsigned long touchStart = 0;   // Время начала касания
bool isOn = false;             // Включена ли лента в данный момент

void setup() {
  pinMode(TOUCH_PIN, INPUT);   // Настраиваем пин сенсора на вход

  strip.begin();               // Инициализация ленты
  strip.setBrightness(150);    // Яркость 150 из 255 (экономия батареи, но ярко)
  strip.show();                // Погасить все диоды при старте
}

void loop() {
  // 1. Читаем состояние сенсора (HIGH = касание)
  int touch = digitalRead(TOUCH_PIN);

  if (touch == HIGH) {
    // === ЕСЛИ ПАЛЕЦ КАСАЕТСЯ ===

    if (!isOn) {
      // Включаем ленту в первый раз (или после выключения)
      isOn = true;
      touchStart = millis();        // Запоминаем момент касания

      // Зажигаем случайный цвет на каждом диоде
      for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t color = strip.Color(random(50, 255), random(50, 255), random(50, 255));
        strip.setPixelColor(i, color);
      }
      strip.show();
    }

    // Проверяем, держит ли палец дольше 1.5 секунды
    if (millis() - touchStart > 1500) {
      // Включаем режим радуги (бегущая волна)
      rainbowSwirl(30);   // Скорость бега: 30 мс между кадрами

      // Ждём, пока палец не уберут
      while (digitalRead(TOUCH_PIN) == HIGH) {
        // пустой цикл ожидания
      }

      // Когда палец убрали, выключаем ленту
      for (int i = 0; i < NUM_LEDS; i++) {
        strip.setPixelColor(i, 0);
      }
      strip.show();
      isOn = false;
    }
  } else {
    // === ПАЛЕЦ НЕ КАСАЕТСЯ ===

    // Если лента включена и прошло больше 5 секунд с момента последнего касания
    if (isOn && (millis() - touchStart > 5000)) {
      // Выключаем ленту
      for (int i = 0; i < NUM_LEDS; i++) {
        strip.setPixelColor(i, 0);
      }
      strip.show();
      isOn = false;
    }
  }
}

// ===========================================
// Функция бегущей радуги
// ===========================================
void rainbowSwirl(int wait) {
  for (int j = 0; j < 256; j += 2) {         // 256 шагов для полного круга цветов
    for (int i = 0; i < NUM_LEDS; i++) {
      // Вычисляем цвет для каждого диода с учётом его позиции и смещения j
      uint32_t color = strip.ColorHSV((i * 65536 / NUM_LEDS + j * 256) % 65536, 255, 200);
      strip.setPixelColor(i, color);
    }
    strip.show();
    delay(wait);

    // Если палец отпущен во время радуги — выходим из функции
    if (digitalRead(TOUCH_PIN) == LOW) {
      break;
    }
  }
}

