#include <Adafruit_NeoPixel.h>

#define LED_PIN 6
#define NUM_LEDS 60
#define TOUCH_PIN 2

Adafruit_NeoPixel strip(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

unsigned long touchStart = 0;
bool isOn = false;

void setup() {
  pinMode(TOUCH_PIN, INPUT);
  strip.begin();
  strip.setBrightness(150);
  strip.show();
}

void loop() {
  int touch = digitalRead(TOUCH_PIN);

  if (touch == HIGH) {
    if (!isOn) {
      isOn = true;
      touchStart = millis();
      for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t color = strip.Color(random(50, 255), random(50, 255), random(50, 255));
        strip.setPixelColor(i, color);
      }
      strip.show();
    }
    if (millis() - touchStart > 1500) {
      rainbowSwirl(30);
      while (digitalRead(TOUCH_PIN) == HIGH) {}
      for (int i = 0; i < NUM_LEDS; i++) strip.setPixelColor(i, 0);
      strip.show();
      isOn = false;
    }
  } else {
    if (isOn && (millis() - touchStart > 5000)) {
      for (int i = 0; i < NUM_LEDS; i++) strip.setPixelColor(i, 0);
      strip.show();
      isOn = false;
    }
  }
}

void rainbowSwirl(int wait) {
  for (int j = 0; j < 256; j += 2) {
    for (int i = 0; i < NUM_LEDS; i++) {
      uint32_t color = strip.ColorHSV((i * 65536 / NUM_LEDS + j * 256) % 65536, 255, 200);
      strip.setPixelColor(i, color);
    }
    strip.show();
    delay(wait);
    if (digitalRead(TOUCH_PIN) == LOW) break;
  }
}
